import { createAsyncThunk } from "@reduxjs/toolkit";
import { forkConversation } from "./fork-conversation.thunk.js";
import { mergeEditedText } from "./content-blocks.util.js";
import { toastDoor } from "../../../../host/ui-slots.js";
const forkAndResubmitFromMessage = createAsyncThunk(
  "messages/forkAndResubmitFromMessage",
  async ({ conversationId, messageId, newContent, surfaceKey }, { dispatch, getState, rejectWithValue }) => {
    const sourceEntry = getState().messages.byConversationId[conversationId];
    const sourceMessage = sourceEntry?.byId?.[messageId];
    if (!sourceMessage) {
      return rejectWithValue({
        // access-errors: ok — browser-local Redux lookup; the message is absent from the loaded conversation slice, no record read involved
        message: `Message ${messageId} not found in conversation ${conversationId}`
      });
    }
    const forkPosition = sourceMessage.position ?? 0;
    const forkResult = await dispatch(
      forkConversation({ conversationId, atPosition: forkPosition })
    ).unwrap();
    const newConversationId = forkResult.conversationId;
    if (typeof newContent === "string") {
      const forkedEntry = getState().messages.byConversationId[newConversationId];
      const editedId = forkedEntry ? Object.values(forkedEntry.byId).find(
        (m) => m.position === forkPosition
      )?.id ?? null : null;
      if (typeof editedId !== "string") {
        return rejectWithValue({
          message: "Couldn't find the edited message on the new fork"
        });
      }
      const { editMessage } = await import("./edit-message.thunk.js");
      const existing = getState().messages.byConversationId[newConversationId]?.byId?.[editedId]?.content;
      await dispatch(
        editMessage({
          conversationId: newConversationId,
          messageId: editedId,
          newContent: mergeEditedText(existing, newContent)
        })
      ).unwrap();
    }
    if (surfaceKey) {
      const { requestSurfaceNavigation } = await import("../../surfaces/request-surface-navigation.thunk.js");
      await dispatch(
        requestSurfaceNavigation({
          surfaceKey,
          conversationId: newConversationId,
          reason: "fork"
        })
      );
    } else {
      const { toast } = await import("../../../../host/notify.js");
      toast.success("Branch created", {
        action: toastDoor("conversation", newConversationId)
      });
    }
    const { executeInstance } = await import("../thunks/execute-instance.thunk.js");
    void dispatch(
      executeInstance({ conversationId: newConversationId, retry: true })
    );
    return { conversationId: newConversationId };
  }
);
export {
  forkAndResubmitFromMessage
};
